// UART testbench for cmtz_mlane_uart. Generated by cmtz/backends/isa_mlane.py;
// expected replies from cmtz/isa/multicore.py. Prints PASS or FAIL.
`timescale 1ns/1ps
module cmtz_mlane_uart_tb;
localparam CPB = 8;
reg clk = 0;
always #5 clk = ~clk;
reg rx = 1'b1;
wire tx;
wire [5:0] leds;
cmtz_mlane_uart #(.CLKS_PER_BIT(CPB), .TIMEOUT_CLKS(6000)) dut (
    .clk(clk), .rx(rx), .tx(tx), .leds(leds));

integer errors = 0, step = 0, i, k, kt;
reg [7:0] got;
reg [7:0] q [0:27];

task tx_byte(input [7:0] b);
    begin
        rx = 1'b0; repeat (CPB) @(posedge clk);
        for (i = 0; i < 8; i = i + 1) begin
            rx = b[i]; repeat (CPB) @(posedge clk);
        end
        rx = 1'b1; repeat (CPB + 2) @(posedge clk);
    end
endtask

reg [7:0] fifo [0:8191];
integer wp = 0, rp = 0, mb;
reg [7:0] mbyte;
always begin : monitor
    @(negedge tx);
    repeat (CPB / 2) @(posedge clk);
    if (tx == 1'b0) begin
        for (mb = 0; mb < 8; mb = mb + 1) begin
            repeat (CPB) @(posedge clk); mbyte[mb] = tx;
        end
        repeat (CPB) @(posedge clk);
        fifo[wp % 8192] = mbyte; wp = wp + 1;
    end
end

task rx_byte;
    begin : rxb
        kt = 0;
        while (rp >= wp) begin
            @(posedge clk); kt = kt + 1;
            if (kt > 400000) begin
                $display("FAIL: step %0d no reply byte", step);
                errors = errors + 1; got = 8'hxx; disable rxb;
            end
        end
        got = fifo[rp % 8192]; rp = rp + 1;
    end
endtask

task rx_expect(input [7:0] want, input [7:0] mask);
    begin
        rx_byte;
        if (((got ^ want) & mask) !== 8'h00) begin
            $display("FAIL: step %0d got %02x expected %02x", step, got, want);
            errors = errors + 1;
        end
    end
endtask

task poll_status;
    begin : poll
        repeat (2000) begin
            tx_byte("Q");
            for (k = 0; k < 28; k = k + 1) begin rx_byte; q[k] = got; end
            if (q[0] != 8'd1) disable poll;
        end
        $display("FAIL: step %0d still running", step);
        errors = errors + 1;
    end
endtask

task chk_q(input integer n, input [7:0] want, input [7:0] mask);
    if (((q[n] ^ want) & mask) !== 8'h00) begin
        $display("FAIL: step %0d status byte %0d = %02x expected %02x",
                 step, n, q[n], want);
        errors = errors + 1;
    end
endtask

task chk_cycles(input integer n);
    if ({q[20], q[21], q[22], q[23]} - {q[16], q[17], q[18], q[19]} !== n) begin
        $display("FAIL: step %0d stamps give %0d cycles, expected %0d", step,
                 {q[20], q[21], q[22], q[23]} - {q[16], q[17], q[18], q[19]}, n);
        errors = errors + 1;
    end
endtask

